SELECT last_restock_month, last_restock_cohort, unique_stores, min_quantity FROM (SELECT MONTH(last_restock) AS last_restock_month, CASE WHEN YEAR(last_restock) < 2024 THEN 'before_2024' WHEN YEAR(last_restock) = 2024 THEN '2024' ELSE 'after_2024' END AS last_restock_cohort, COUNT(DISTINCT quantity) AS unique_stores, MIN(quantity) AS min_quantity FROM inventory WHERE product_id IN (1, 5, 8, 10) GROUP BY MONTH(last_restock), CASE WHEN YEAR(last_restock) < 2024 THEN 'before_2024' WHEN YEAR(last_restock) = 2024 THEN '2024' ELSE 'after_2024' END) AS x WHERE unique_stores > 4
